create or replace function public.reabrir_fechamento(p_fechamento uuid,p_motivo text) returns void language plpgsql security invoker as $$ begin if coalesce(trim(p_motivo),'')='' then raise exception 'Motivo obrigatório'; end if; update public.fechamentos set status='aberto',motivo_reabertura=p_motivo,reaberto_por=auth.uid(),reaberto_em=now() where id=p_fechamento; end $$;
create or replace function public.vincular_descontos_pagamento(p_pagamento uuid,p_motoboy uuid,p_mes smallint,p_ano smallint) returns void language plpgsql security invoker as $$ begin update public.vales_extravios set pagamento_motoboy_id=p_pagamento,status='descontado' where motoboy_id=p_motoboy and mes_desconto=p_mes and ano_desconto=p_ano and status='pendente' and pagamento_motoboy_id is null; end $$;

